def solve():
    p = 61

    # 1. Calculate N(T) = #{(a, b) | a^2 + b^2 == T mod p}
    N = [0] * p
    for a in range(p):
        for b in range(p):
            T = (a*a + b*b) % p
            N[T] += 1

    # 2. Calculate M(j) = #{(c) | c^3 == j mod p}
    M = [0] * p
    for c in range(p):
        j = (c**3) % p
        M[j] += 1

    # 3. Calculate C_k = sum_{T=0}^{p-1} N(T) * M(k-T mod p)
    C = [0] * p
    for k in range(p):
        sum_val = 0
        for T in range(p):
            # k - T mod p
            j = (k - T) % p
            sum_val += N[T] * M[j]
        C[k] = sum_val

    # Store results
    print("C_k values:", C)

solve()

p = 61

# Step 1: Calculate N_2(R) = number of solutions to a^2 + b^2 = R (mod p)
N_2 = {}
for R in range(p):
    count = 0
    for a in range(p):
        a2 = (a * a) % p
        for b in range(p):
            b2 = (b * b) % p
            if (a2 + b2) % p == R:
                count += 1
    N_2[R] = count

# Step 2: Calculate N_X(r) = number of solutions to a^2 + b^2 + c^3 = r (mod p)
N_X = {}
for r in range(p):
    count = 0
    for c in range(p):
        c3 = (c * c * c) % p
        R = (r - c3) % p
        # Number of solutions for a^2 + b^2 = R
        count += N_2[R]
    N_X[r] = count

# Step 3: Calculate N_Y(k) = number of solutions to d^3 = k (mod p)
N_Y = {}
# We use the analytical result from the notes for efficiency and correctness:
# p=61, g=3.
for k in range(p):
    if k == 0:
        N_Y[k] = 1
    else:
        # Check if k is a cubic residue: k^20 = 1 (mod 61)
        # Use modular exponentiation
        if pow(k, 20, p) == 1:
            N_Y[k] = 3
        else:
            N_Y[k] = 0

# Step 4: Calculate N_0 = sum_{r=0}^{60} N_X(r) * N_Y(r)
N_0 = 0
for r in range(p):
    N_0 += N_X[r] * N_Y[r]

print(f"N_X(0) = {N_X[0]}")
print(f"N_Y(0) = {N_Y[0]}")
print(f"Total number of solutions N_0 = {N_0}")
